Hello! If this is you are trying to achieve you can do it by this method. 


const [showMoreTriggered, setShowMoreTriggered] = React.useState<boolean>(false)

<RefinementList
                  attribute="brand"
                  sortBy={[sorting]}
                  limit={showMoreTriggered ? 20 : 5}
                  showMore={true}
                  showMoreLimit={21}
                  onClick = {() => setShowMoreTriggered(!showMoreTriggered)}
                />
